// Hand-written `express` stub for the flowatlas fixture suite.
//
// The real types live in `@types/express`, which re-exports most of them from
// `@types/express-serve-static-core`; the adapter lists both packages for that
// reason. Here there is one file, because what is being tested is the shapes the
// reader matches on and not where a package puts its declarations.
//
// Only what the fixture writes exists: an application and a router that answer
// to the same methods, a handler signature, and a request whose body may carry
// a declared type.

export type NextFunction = (error?: unknown) => void;

export interface Request<Params = Record<string, string>, ResBody = unknown, ReqBody = unknown> {
  params: Params;
  query: Record<string, string>;
  /** Untyped unless the route says otherwise, which is the point of it. */
  body: ReqBody;
  header(name: string): string | undefined;
}

export interface Response<ResBody = unknown> {
  status(code: number): Response<ResBody>;
  json(body: ResBody): Response<ResBody>;
  send(body?: unknown): Response<ResBody>;
}

export type RequestHandler = (
  req: Request<any, any, any>,
  res: Response,
  next: NextFunction,
) => unknown;

/** Everything both an application and a router answer to. */
export interface IRouter {
  get(path: string, ...handlers: RequestHandler[]): this;
  post(path: string, ...handlers: RequestHandler[]): this;
  put(path: string, ...handlers: RequestHandler[]): this;
  patch(path: string, ...handlers: RequestHandler[]): this;
  delete(path: string, ...handlers: RequestHandler[]): this;
  options(path: string, ...handlers: RequestHandler[]): this;
  head(path: string, ...handlers: RequestHandler[]): this;
  all(path: string, ...handlers: RequestHandler[]): this;
  use(...handlers: RequestHandler[]): this;
  use(path: string, ...handlers: Array<RequestHandler | IRouter>): this;
}

export interface Router extends IRouter {}

export interface Application extends IRouter {
  /** One argument, and a setting rather than a route: `app.get('env')`. */
  get(name: string): unknown;
  get(path: string, ...handlers: RequestHandler[]): this;
  set(name: string, value: unknown): this;
  listen(port: number, callback?: () => void): unknown;
}

export interface Express extends Application {}

export interface RouterOptions {
  mergeParams?: boolean;
  strict?: boolean;
}

export declare function Router(options?: RouterOptions): Router;

declare function express(): Express;

declare namespace express {
  function json(): RequestHandler;
  function urlencoded(options?: { extended?: boolean }): RequestHandler;
}

export default express;
